package com.primehr.succession.domain;

import com.primehr.integration.administrative.AdministrativePositionTarget;
import com.primehr.positionprofile.domain.PositionTargetType;
import com.primehr.rsp.domain.RspAuditedEntity;
import com.primehr.shared.exception.IllegalLifecycleTransitionException;
import jakarta.persistence.*;
import java.time.*;

@Entity
@Table(name="succession_critical_position_designation")
public class SuccessionCriticalPositionDesignation extends RspAuditedEntity {
    public enum Status{DRAFT,SUBMITTED,APPROVED,REJECTED,RETIRED}
    @Enumerated(EnumType.STRING) @Column(name="target_type",nullable=false,length=20) private PositionTargetType targetType;
    @Column(name="target_id",nullable=false) private Long targetId; @Column(name="job_position_id",nullable=false) private Long jobPositionId; @Column(name="position_name",nullable=false,length=250) private String positionName; @Column(name="plantilla_id") private Long plantillaId; @Column(name="plantilla_name",length=250) private String plantillaName; @Column(name="source_fingerprint",nullable=false,length=120) private String sourceFingerprint; @Column(name="source_fetched_at",nullable=false) private Instant sourceFetchedAt;
    @Column(name="framework_version_id",nullable=false,length=36) private String frameworkVersionId; @Column(name="framework_definition_version",nullable=false) private int frameworkDefinitionVersion; @Column(name="framework_fingerprint",nullable=false,length=120) private String frameworkFingerprint; @Column(name="charter_version_id",nullable=false,length=36) private String charterVersionId;
    @Column(nullable=false,length=200) private String title; @Column(nullable=false,length=4000) private String justification; @Column(name="assessment_date",nullable=false) private LocalDate assessmentDate; @Column(name="effective_from") private LocalDate effectiveFrom; @Column(name="effective_to") private LocalDate effectiveTo; @Column(name="review_date",nullable=false) private LocalDate reviewDate; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private Status status;
    @Column(name="submitted_by",length=100) private String submittedBy; @Column(name="submitted_at") private Instant submittedAt; @Column(name="decision_by",length=100) private String decisionBy; @Column(name="decision_at") private Instant decisionAt; @Column(name="decision_reason",length=2000) private String decisionReason;
    protected SuccessionCriticalPositionDesignation() { }
    public SuccessionCriticalPositionDesignation(String agencyId,AdministrativePositionTarget target,String frameworkVersionId,int frameworkDefinitionVersion,String frameworkFingerprint,String charterVersionId,String title,String justification,LocalDate assessmentDate,LocalDate reviewDate){super(agencyId);if(target==null)throw new IllegalArgumentException("position target is required");this.targetType=target.type();this.targetId=target.targetId();this.jobPositionId=target.jobPositionId();this.positionName=requiredText(target.jobPositionName(),"positionName");this.plantillaId=target.plantillaId();this.plantillaName=optionalText(target.plantillaName());this.sourceFingerprint=requiredText(target.sourceFingerprint(),"sourceFingerprint");this.sourceFetchedAt=target.fetchedAt();this.frameworkVersionId=requiredText(frameworkVersionId,"frameworkVersionId");this.frameworkDefinitionVersion=frameworkDefinitionVersion;this.frameworkFingerprint=requiredText(frameworkFingerprint,"frameworkFingerprint");this.charterVersionId=requiredText(charterVersionId,"charterVersionId");this.status=Status.DRAFT;update(title,justification,assessmentDate,reviewDate);}
    public void update(String title,String justification,LocalDate assessmentDate,LocalDate reviewDate){requireDraft();this.title=requiredText(title,"title");this.justification=requiredText(justification,"justification");if(assessmentDate==null||reviewDate==null||reviewDate.isBefore(assessmentDate))throw new IllegalArgumentException("reviewDate must be on or after assessmentDate");this.assessmentDate=assessmentDate;this.reviewDate=reviewDate;}
    public void submit(String actor,Instant at){requireDraft();status=Status.SUBMITTED;submittedBy=requiredText(actor,"actor");submittedAt=at;}
    public void approve(String actor,String reason,LocalDate from,LocalDate to,Instant at){if(status!=Status.SUBMITTED)throw new IllegalLifecycleTransitionException("Only submitted designations may be approved");if(actor.equalsIgnoreCase(submittedBy))throw new IllegalArgumentException("Submitter cannot approve the same designation");if(from==null||to!=null&&to.isBefore(from))throw new IllegalArgumentException("Invalid designation effectivity");status=Status.APPROVED;effectiveFrom=from;effectiveTo=to;decisionBy=requiredText(actor,"actor");decisionReason=requiredText(reason,"reason");decisionAt=at;}
    public void reject(String actor,String reason,Instant at){if(status!=Status.SUBMITTED)throw new IllegalLifecycleTransitionException("Only submitted designations may be rejected");if(actor.equalsIgnoreCase(submittedBy))throw new IllegalArgumentException("Submitter cannot decide the same designation");status=Status.REJECTED;decisionBy=requiredText(actor,"actor");decisionReason=requiredText(reason,"reason");decisionAt=at;}
    public void retire(String actor,String reason,Instant at){if(status!=Status.APPROVED)throw new IllegalLifecycleTransitionException("Only approved designations may be retired");status=Status.RETIRED;decisionBy=requiredText(actor,"actor");decisionReason=requiredText(reason,"reason");decisionAt=at;if(effectiveTo==null)effectiveTo=LocalDate.now(ZoneId.of("Asia/Manila"));}
    private void requireDraft(){if(status!=Status.DRAFT)throw new IllegalLifecycleTransitionException("Only draft designations may be changed");}
    public PositionTargetType getTargetType(){return targetType;} public Long getTargetId(){return targetId;} public Long getJobPositionId(){return jobPositionId;} public String getPositionName(){return positionName;} public Long getPlantillaId(){return plantillaId;} public String getPlantillaName(){return plantillaName;} public String getSourceFingerprint(){return sourceFingerprint;} public Instant getSourceFetchedAt(){return sourceFetchedAt;} public String getFrameworkVersionId(){return frameworkVersionId;} public int getFrameworkDefinitionVersion(){return frameworkDefinitionVersion;} public String getFrameworkFingerprint(){return frameworkFingerprint;} public String getCharterVersionId(){return charterVersionId;} public String getTitle(){return title;} public String getJustification(){return justification;} public LocalDate getAssessmentDate(){return assessmentDate;} public LocalDate getEffectiveFrom(){return effectiveFrom;} public LocalDate getEffectiveTo(){return effectiveTo;} public LocalDate getReviewDate(){return reviewDate;} public Status getStatus(){return status;} public String getSubmittedBy(){return submittedBy;} public Instant getSubmittedAt(){return submittedAt;} public String getDecisionBy(){return decisionBy;} public Instant getDecisionAt(){return decisionAt;} public String getDecisionReason(){return decisionReason;}
}
